import json
import numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
S=json.load(open('/app/output/spec.json'))
AX=np.array(S['proprio']['axis']); JP=np.array(S['proprio']['position_m'])
LN=S['links']['names']; PARENTS=S['links']['parent']; CM=np.array(S['links']['com_m']); MASS=np.array(S['links']['mass_kg'])
JMAP={n+'_link':i for i,n in enumerate(S['proprio']['joints'])}
def fk(q):
 T={None:np.eye(4)}; ans={}
 for n,p,c in zip(LN,PARENTS,CM):
  t=T[p].copy()
  if n in JMAP:
   j=JMAP[n];R=Rotation.from_rotvec(AX[j]*q[j]).as_matrix();a=np.eye(4);a[:3,:3]=R;a[:3,3]=JP[j]-R@JP[j];t=t@a
  T[n]=t;ans[n]=t[:3,:3]@c+t[:3,3]
 ans['com']=np.average(np.array([ans[n] for n in LN]),weights=MASS,axis=0)
 return ans,T

def imu_rotation(v):
 g=np.asarray(v)[41:44]
 axis=np.cross(g,[0,0,-1]);n=np.linalg.norm(axis)
 return Rotation.from_rotvec(axis/max(n,1e-8)*np.arctan2(n,-g[2])).as_matrix()

def describe(v):
 q=np.array(v[:19]);pts,T=fk(q);R=imu_rotation(v);pts={k:R@x for k,x in pts.items()};feet=(pts['left_ankle_link']+pts['right_ankle_link'])/2
 return {k:np.round(pts[k]-feet,4).tolist() for k in ['com','pelvis','left_hand','right_hand']}

def arm_ik(target,side='left',q=None):
 if q is None:q=np.zeros(19)
 q=q.copy();ids=np.arange(11,15) if side=='left' else np.arange(15,19)
 bounds=np.array(S['action_types']['joint_position']['range_rad'])[ids]
 def err(a):
  qq=q.copy();qq[ids]=a;p,_=fk(qq)
  return np.r_[5*(p[side+'_hand']-target),.03*(a-q[ids])]
 opt=least_squares(err,q[ids],bounds=(bounds[:,0],bounds[:,1]))
 q[ids]=opt.x
 return q, fk(q)[0][side+'_hand']
if __name__=='__main__':
 import sys
 v=json.load(open(sys.argv[1]))['proprio']['now'];print(describe(v))
 for target in [[.5,.5,.2],[.6,.45,.1],[.55,.55,.15]]:
  q,p=arm_ik(target);print(target,q[11:15],p)
